  with torch.inference_mode():aw=walk(base,gait);astop=stop(base,gait);ah=hold.mean(obs)
  pre=torch.where((step<switch)[:,None],aw,astop);a=torch.where((completion>=0)[:,None],ah[:n],pre[:n]);a=torch.cat((a,pre[n:]),0);arrays["action"].append(a[:n].cpu());_,_,done,extras=world.wrapped.step(a);done=done.bool();timeout=extras.get("time_outs",torch.zeros_like(done)).bool();fall|=done[:n]&~timeout[:n];force=world.sensor.data.net_forces_w_history[:n,-1,world.sf,:].norm(dim=-1);contact=force>5;feet=world.robot.data.body_lin_vel_w[:n,world.rf,:2].norm(dim=-1);bad=((feet>.55)&contact).any(1);slip_streak=torch.where(bad,slip_streak+1,torch.zeros_like(slip_streak));slip|=slip_streak>=5;impact|=force.amax(1)>3500;jv=world.robot.data.joint_vel[:n];ja=(jv-prev_jv)/DT;torque=world.robot.data.applied_torque[:n];vr=jv.abs().div(world.limits[:n].clamp_min(1e-6)).amax(1);eff=world.robot.data.joint_effort_limits[:n].abs().clamp_min(1e-6);tr=torque.abs().div(eff).amax(1);vstreak=torch.where(vr>.95,vstreak+1,torch.zeros_like(vstreak));tstreak=torch.where(tr>.95,tstreak+1,torch.zeros_like(tstreak));vsat|=vstreak>=5;tsat|=tstreak>=5;lv=world.robot.data.root_lin_vel_w[:n];av=world.robot.data.root_ang_vel_w[:n];grav=world.robot.data.projected_gravity_b[:n];rp=torch.acos((-grav[:,2]).clamp(-1,1));s=world.robot.data.root_lin_vel_b[:n,:2].norm(dim=1);y=world.robot.data.root_ang_vel_b[:n,2].abs();good=(s<=.08)&(y<=.08);streak=torch.where(good,streak+1,torch.zeros_like(streak));new=(completion<0)&(streak>=25)&((step-24)<75);completion[new]=step;speed.append(s.cpu());yaw.append(y.cpu())
  vals={"joint_vel":jv,"joint_acc":ja,"torque":torque,"base_lin_acc":(lv-prev_lv)/DT,"base_ang_acc":(av-prev_av)/DT,"roll_pitch":rp,"contact":contact,"foot_slip":bad,"impact_force":force.amax(1),"vel_ratio":vr,"torque_ratio":tr,"root_pos":world.robot.data.root_pos_w[:n]}
