 for j,e in enumerate(entries):
  comp=int(completion[j]);safe=bool(eligible[j] and comp>=0 and not fall[j] and not slip[j] and not impact[j] and not vsat[j] and not tsat[j]);start=comp+1;end=start+100;hold_ok=False
