  trans.append({"condition_id":e["condition"]["formal_condition_id"],"variant":e["condition"]["variant"],"switch_step":sw,"normalized_action_delta_max":float(ad.norm(dim=1).max()),"switch_action_l2":float((arrays["action"][sw,j]-arrays["action"][sw-1,j]).norm()),"joint_target_delta_rad_max":float((ad*.5).abs().max()),"joint_velocity_max":float(arrays["joint_vel"][lo:hi+1,j].abs().max()),"joint_acceleration_max":float(arrays["joint_acc"][lo:hi+1,j].abs().max()),"actuator_torque_max":float(arrays["torque"][lo:hi+1,j].abs().max()),"velocity_ratio_max":float(arrays["vel_ratio"][lo:hi+1,j].max()),"torque_ratio_max":float(arrays["torque_ratio"][lo:hi+1,j].max()),"base_linear_acceleration_max":float(arrays["base_lin_acc"][lo:hi+1,j].norm(dim=1).max()),"base_angular_acceleration_max":float(arrays["base_ang_acc"][lo:hi+1,j].norm(dim=1).max()),"roll_pitch_max":float(arrays["roll_pitch"][lo:hi+1,j].max()),"contact_states":arrays["contact"][lo:hi+1,j].int().tolist(),"foot_slip":bool(arrays["foot_slip"][lo:hi+1,j].any()),"impact_force_max":float(arrays["impact_force"][lo:hi+1,j].max()),"root_state_discontinuity":bool((~torch.isfinite(root_delta)).any() or root_delta.norm(dim=1).max()>1),"contact_buffer_corruption":bool((~torch.isfinite(arrays["impact_force"][lo:hi+1,j])).any()),"nan_inf":int(any((~torch.isfinite(arrays[k][lo:hi+1,j])).any() for k in ("action","joint_vel","joint_acc","torque","base_lin_acc","base_ang_acc","roll_pitch")))})
